insert into subjects(id,name,is_available) values ('sat','SAT vocabulary',true),('medical','Medical foundations',true),('math','Math',false),('chem','Chemistry',false) on conflict(id) do nothing;
insert into scenes(id,subject_id,title) values ('market','sat','The curious little market') on conflict(id) do nothing;
insert into facts(id,topic_id,fact_text,order_index) values ('lucid','market','Lucid: Clear and easy to understand',0) on conflict(id) do nothing;
insert into mnemonics(id,fact_id,technique_type,style,story_text) values ('lucid','lucid','Method of loci + visual association','storybook','Lift a perfectly clear lantern. Its light makes a tangled explanation suddenly easy to follow. Clear light, clear meaning: lucid.') on conflict(id) do nothing;
insert into facts(id,topic_id,fact_text,order_index) values ('meticulous','market','Meticulous: Extremely careful about details',1) on conflict(id) do nothing;
insert into mnemonics(id,fact_id,technique_type,style,story_text) values ('meticulous','meticulous','Method of loci + visual association','storybook','Inspect every tiny gear in a pocket watch. No speck escapes the magnifying glass. That extraordinary attention to detail is meticulous.') on conflict(id) do nothing;
insert into facts(id,topic_id,fact_text,order_index) values ('ephemeral','market','Ephemeral: Lasting for a very short time',2) on conflict(id) do nothing;
insert into mnemonics(id,fact_id,technique_type,style,story_text) values ('ephemeral','ephemeral','Method of loci + visual association','storybook','A butterfly appears, flutters once, and dissolves into dots. You have only a moment to see it. Its brief existence is ephemeral.') on conflict(id) do nothing;
insert into facts(id,topic_id,fact_text,order_index) values ('resilient','market','Resilient: Able to recover after difficulty',3) on conflict(id) do nothing;
insert into mnemonics(id,fact_id,technique_type,style,story_text) values ('resilient','resilient','Method of loci + visual association','storybook','A pot breaks, but the bent sapling springs upright again. You tie a bandage around its trunk. The recovering tree is resilient.') on conflict(id) do nothing;
insert into facts(id,topic_id,fact_text,order_index) values ('avarice','market','Avarice: Extreme greed for wealth',4) on conflict(id) do nothing;
insert into mnemonics(id,fact_id,technique_type,style,story_text) values ('avarice','avarice','Method of loci + visual association','storybook','A giant hand clutches a treasure chest so tightly it cannot share a single coin. We call this excessive hunger for riches avarice.') on conflict(id) do nothing;
insert into facts(id,topic_id,fact_text,order_index) values ('ambiguous','market','Ambiguous: Open to more than one interpretation',5) on conflict(id) do nothing;
insert into mnemonics(id,fact_id,technique_type,style,story_text) values ('ambiguous','ambiguous','Method of loci + visual association','storybook','The sign points both left and right with no explanation. You can read its message two ways. A message with multiple plausible meanings is ambiguous.') on conflict(id) do nothing;
insert into facts(id,topic_id,fact_text,order_index) values ('candid','market','Candid: Truthful and straightforward',6) on conflict(id) do nothing;
insert into mnemonics(id,fact_id,technique_type,style,story_text) values ('candid','candid','Visual association','storybook','Open a notebook with nothing hidden between its pages. A candid answer is open and honest.') on conflict(id) do nothing;
insert into facts(id,topic_id,fact_text,order_index) values ('pragmatic','market','Pragmatic: Focused on practical results',7) on conflict(id) do nothing;
insert into mnemonics(id,fact_id,technique_type,style,story_text) values ('pragmatic','pragmatic','Visual association','storybook','Choose the watch that actually works over the fanciest display. A pragmatic choice solves the real problem.') on conflict(id) do nothing;
insert into facts(id,topic_id,fact_text,order_index) values ('tenacious','market','Tenacious: Persistent; holding firmly',8) on conflict(id) do nothing;
insert into mnemonics(id,fact_id,technique_type,style,story_text) values ('tenacious','tenacious','Visual association','storybook','Hold onto a clue even when the investigation gets difficult. Picture the firm grip: tenacious means persistent.') on conflict(id) do nothing;
insert into facts(id,topic_id,fact_text,order_index) values ('elusive','market','Elusive: Difficult to find, catch, or achieve',9) on conflict(id) do nothing;
insert into mnemonics(id,fact_id,technique_type,style,story_text) values ('elusive','elusive','Visual association','storybook','The butterfly slips away whenever you reach for it. Something elusive is hard to catch or pin down.') on conflict(id) do nothing;
